/**
 * Alert card — v2. Six variants, one component.
 *
 * Design source: Figma YEmjkKS4xaA827Zm8w3oXx, fetched one variant node at a
 * time (fetching the parent variant set merges them and returns wrong assets):
 *   198374:72716  Mobile          308x178 — the 375px treatment, two actions
 *   198374:56324  Water event     308x136
 *   198374:56322  Ignored         308x136
 *   198437:81920  Sensors         308x136 — sensor groups, error badges
 *   198378:79411  Sensors_Errors  308x136 — pager on top, connected badges
 *   198374:72758  empty           308x136 — "Everything looks good!"
 *
 * Figma's own class strings are kept VERBATIM. Every var() it emits carries its
 * literal design fallback (text-[color:var(--colors\/slate\/600,#45556c)]), and
 * none of those token names exist in src/index.css, so the fallback is what
 * renders — the exact design value, with no token wiring. Do not "translate"
 * them into project utilities; that is what broke the previous pass.
 *
 * Two mechanical consequences of keeping them verbatim:
 *
 *  1. The `\/` has to survive to the DOM. JSX attribute strings are raw — no
 *     escape processing — so className="…\/…" is safe. A *JS* string literal is
 *     not: "\/" collapses to "/", while the Tailwind rule is generated from the
 *     raw source text (which still has the backslash), and the two stop
 *     matching. Every shared class string below is therefore String.raw``.
 *  2. Figma emits font-[family-name:var(--font\/family\/sans,'Figtree:Medium')].
 *     "Figtree:Medium" is a family+style label, not a CSS family: it matches
 *     nothing and the text drops to the UA default font. That one class is
 *     swapped for the project's `font-sans` (Figtree) / `font-mono-label`
 *     (Geist). Weight still comes from Figma's own font-[var(--font\/weight…)].
 *
 * Assets are inlined — Figma asset URLs expire in ~7 days, so nothing here may
 * reference one at runtime.
 */

import { Badge } from '@/components/ui/badge'
import { Button } from '@/components/ui/button'
import { Waves, WifiDisconnected02 } from '@/v2/icons'

/* ── Inlined Figma assets ─────────────────────────────────────────────────── */

/**
 * Tabler chevron-left / chevron-right, 16x16, #62748E @1.33.
 *
 * These are the trap in this card. `get_design_context` returns the Button
 * component's *default* Icon Placeholder for both slots — a Huge Icons smile
 * face — under a variable named `imgTablerIconsChevronLeft`. get_metadata on
 * the pager button (198379:80025) names the real instances
 * "Tabler Icons / chevron-left" and "Tabler Icons / chevron-right"; fetching
 * those two nodes individually returns the geometry below. The smile also
 * arrived wrapped in `-rotate-180 -scale-x-100`, which belongs to the
 * placeholder and not to these, so it is gone. #62748E in every variant, so the
 * shipped stroke stays rather than currentColor.
 */
function ChevronLeft({ className }) {
  return (
    <svg width="16" height="16" viewBox="0 0 16 16" fill="none" xmlns="http://www.w3.org/2000/svg"
      className={className} aria-hidden="true" focusable="false">
      <path d="M10 4L6 8L10 12" stroke="#62748E" strokeWidth="1.33" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  )
}

function ChevronRight({ className }) {
  return (
    <svg width="16" height="16" viewBox="0 0 16 16" fill="none" xmlns="http://www.w3.org/2000/svg"
      className={className} aria-hidden="true" focusable="false">
      <path d="M6 4L10 8L6 12" stroke="#62748E" strokeWidth="1.33" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  )
}

/* Remix Icons / flood-line. Ships twice — 16px @#62748E in the group header,
   19.2px @#FB2C36 in the error badge — the same path scaled 1.2x, so one
   16-unit viewBox recoloured to currentColor covers both tints. */
function FloodLine({ size = 16, className }) {
  return (
    <svg width={size} height={size} viewBox="0 0 16 16" fill="none" xmlns="http://www.w3.org/2000/svg"
      className={className} aria-hidden="true" focusable="false">
      <path d="M10.6667 11.6483C11.3744 12.2816 12.3089 12.6667 13.3333 12.6667H14.6667V14.0001H13.3333C12.3619 14.0001 11.4511 13.7403 10.6665 13.2865C9.8828 13.7402 8.97173 14.0001 8 14.0001C7.02853 14.0001 6.11771 13.7403 5.33323 13.2865C4.54947 13.7402 3.63842 14.0001 2.66667 14.0001H1.33333V12.6667H2.66667C3.69142 12.6667 4.62617 12.2814 5.33342 11.6483C6.04109 12.2816 6.9756 12.6667 8 12.6667C9.02473 12.6667 9.95953 12.2814 10.6667 11.6483ZM8.38227 1.02144L8.44847 1.07441L15.3333 7.3334H13.3333V11.3334C12.8659 11.3334 12.4172 11.2532 12.0002 11.1059L12 6.10473L8 2.46807L4 6.10407L4.00083 11.1055C3.6432 11.232 3.26217 11.3091 2.86599 11.3285L2.66667 11.3334V7.3334H0.666667L7.55153 1.07441C7.78467 0.862513 8.1304 0.844853 8.38227 1.02144Z" fill="currentColor" />
    </svg>
  )
}

/* Tabler Icons / brand-drops. Same two sizes as flood-line, but the 19.2px copy
   is drawn at stroke 1 rather than 1.2635, so the weight is a prop expressed in
   16-unit user space (0.8333 renders as 1px once scaled to 19.2). */
function BrandDrops({ size = 16, strokeWidth = 1.2635, className }) {
  return (
    <svg width={size} height={size} viewBox="0 0 16 16" fill="none" xmlns="http://www.w3.org/2000/svg"
      className={className} aria-hidden="true" focusable="false">
      <path d="M11.758 4.944C12.5069 5.68049 13.0187 6.62394 13.2278 7.65331C13.4369 8.68268 13.3336 9.75104 12.9313 10.7213C12.5253 11.6939 11.8402 12.5244 10.9625 13.108C10.0848 13.6915 9.05395 14.0019 8 14C6.94616 14.0018 5.91541 13.6913 5.03787 13.1078C4.16033 12.5243 3.47532 11.6938 3.06933 10.7213C2.66696 9.7511 2.56362 8.68278 2.77256 7.65342C2.98149 6.62405 3.49319 5.68057 4.242 4.944L8 1.33333L11.758 4.944Z" stroke="currentColor" strokeWidth={strokeWidth} strokeLinecap="round" strokeLinejoin="round" />
      <path d="M9.644 7.282C9.97273 7.61555 10.1965 8.03811 10.2878 8.49745C10.379 8.9568 10.3337 9.43281 10.1573 9.86667C9.98471 10.2982 9.68714 10.6683 9.30278 10.9296C8.91842 11.191 8.46477 11.3315 8 11.3333C7.53523 11.3315 7.08159 11.191 6.69722 10.9296C6.31286 10.6683 6.01529 10.2982 5.84267 9.86667C5.66635 9.43281 5.621 8.9568 5.71223 8.49745C5.80346 8.03811 6.02727 7.61555 6.356 7.282L8 5.66667L9.644 7.282Z" stroke="currentColor" strokeWidth={strokeWidth} strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  )
}

/* Phosphor Icons / dots-three — a 14x14 asset drawn into a 12x14 slot (hence
   preserveAspectRatio="none"), #45556C in both sensor variants, so the shipped
   fill stays. */
function DotsThree({ className }) {
  return (
    <svg viewBox="0 0 14 14" fill="none" xmlns="http://www.w3.org/2000/svg"
      preserveAspectRatio="none" className={className} aria-hidden="true" focusable="false">
      <path d="M7 7.65625C7.36244 7.65625 7.65625 7.36244 7.65625 7C7.65625 6.63756 7.36244 6.34375 7 6.34375C6.63756 6.34375 6.34375 6.63756 6.34375 7C6.34375 7.36244 6.63756 7.65625 7 7.65625Z" fill="#45556C" />
      <path d="M10.7188 7.65625C11.0812 7.65625 11.375 7.36244 11.375 7C11.375 6.63756 11.0812 6.34375 10.7188 6.34375C10.3563 6.34375 10.0625 6.63756 10.0625 7C10.0625 7.36244 10.3563 7.65625 10.7188 7.65625Z" fill="#45556C" />
      <path d="M3.28125 7.65625C3.64369 7.65625 3.9375 7.36244 3.9375 7C3.9375 6.63756 3.64369 6.34375 3.28125 6.34375C2.91881 6.34375 2.625 6.63756 2.625 7C2.625 7.36244 2.91881 7.65625 3.28125 7.65625Z" fill="#45556C" />
    </svg>
  )
}

/* Huge Icons / wifi-connected-02 — the healthy counterpart of the
   WifiDisconnected02 that src/v2/icons already owns. 13.368x10.968 is the path
   box (12x9.6) plus the 1.368 stroke bleed, which is the box Figma positions,
   so it is kept rather than normalised to a square. */
function WifiConnected02({ className }) {
  return (
    <svg viewBox="0 0 13.368 10.968" fill="none" xmlns="http://www.w3.org/2000/svg"
      preserveAspectRatio="none" className={className} aria-hidden="true" focusable="false">
      <path d="M10.584 5.184C8.32345 3.184 5.18402 3.184 2.78401 5.184" stroke="currentColor" strokeWidth="1.368" strokeLinecap="round" strokeLinejoin="round" />
      <path d="M0.684015 3.084C4.47349 -0.115986 8.89454 -0.115992 12.684 3.08393" stroke="currentColor" strokeWidth="1.368" strokeLinecap="round" strokeLinejoin="round" />
      <path d="M4.88401 9.08404C4.88401 9.08404 5.48401 9.08404 6.08401 10.284C6.08401 10.284 7.56997 7.94503 9.08401 6.98459" stroke="currentColor" strokeWidth="1.368" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  )
}

/* The empty state's illustration is a raster in the design (a 1448x1086 PNG),
   not an SVG. It is downsampled to 315px — 3x the 105px box it renders in — and
   inlined as a data URI: a Figma asset URL would 404 within a week, and this
   task ships exactly one file so it cannot live in public/. */
const EMPTY_ART = 'data:image/png;base64,'

/* ── Figma class strings ───────────────────────────────────────────────────
 * String.raw so the `\/` reaches the DOM intact (see header note 1). Anything
 * used in exactly one place is written inline as a JSX attribute instead,
 * which is raw already. */

/** Two fully-transparent drop shadows Figma stamps on every Button instance. */
const CTRL_SHADOW = String.raw`drop-shadow-[var(--shadow\/x,0px)_var(--shadows\/scale\/none\/y,0px)_calc(var(--shadows\/scale\/none\/blur,0px)/2)_var(--shadows\/color\/transparent,rgba(0,0,0,0)),var(--shadow\/x,0px)_var(--shadow\/control\/layer-1\/y,0px)_calc(var(--shadow\/control\/layer-1\/blur,0px)/2)_var(--shadow\/control\/layer-1\/color,rgba(0,0,0,0))]`

const PAGER_BTN = String.raw`bg-[var(--colors\/slate\/100,#f1f5f9)] content-stretch cursor-pointer flex gap-[var(--spacing\/1,4px)] h-[24px] items-center justify-center px-[var(--pro\/space\/1,4px)] py-[var(--p-0,0px)] relative rounded-[var(--component\/button\/size-xs\/radius,26px)] shrink-0`
const PAGER_LABEL = String.raw`[word-break:break-word] font-sans font-medium leading-[0] relative shrink-0 text-[color:var(--secondary-foreground,#171717)] text-[length:var(--text\/button-xs\/size,12px)] whitespace-nowrap`
const PAGER_SPAN = String.raw`leading-[var(--text\/button-xs\/size,12px)]`
const ICON_SLOT = 'content-stretch flex flex-col items-center justify-center overflow-clip relative shrink-0 size-[16px]'

const BTN_BLUE = String.raw`bg-[#f2f6ff] border border-[var(--wint-blue-accent,#0b81f8)] border-solid content-stretch cursor-pointer flex gap-[var(--spacing\/1,4px)] h-[24px] items-center justify-center px-[var(--component\/button\/size-xs\/px,10px)] py-[var(--p-0,0px)] relative rounded-[var(--component\/button\/size-xs\/radius,26px)] shrink-0`
const BTN_BLUE_LABEL = String.raw`[word-break:break-word] font-sans font-medium leading-[var(--text\/button-xs\/size,12px)] relative shrink-0 text-[color:var(--wint-blue-accent,#0b81f8)] text-[length:var(--text\/button-xs\/size,12px)] whitespace-nowrap`

const META_ROW = String.raw`[word-break:break-word] content-stretch flex gap-[7px] items-center relative shrink-0 text-[12px] whitespace-nowrap`
const META_LABEL = String.raw`font-sans font-[var(--font\/weight\/font-normal,400)] leading-[var(--text\/xs\/lh-snug,16.5px)] overflow-hidden relative shrink-0 text-[color:var(--colors\/slate\/500,#62748e)] text-ellipsis`
const META_TIME = String.raw`font-sans font-[var(--font\/weight\/font-normal,400)] leading-[var(--text\/xs\/lh-none,12px)] overflow-hidden relative shrink-0 text-[color:var(--colors\/slate\/900,#0f172b)] text-ellipsis`
const META_DURATION = String.raw`font-sans font-[var(--font\/weight\/font-semibold,600)] leading-[var(--text\/xs\/lh-none,12px)] overflow-hidden relative shrink-0 text-[color:var(--colors\/slate\/900,#0f172b)] text-ellipsis`

const AVATAR_ALERT = String.raw`bg-[var(--colors\/red\/100,#ffe2e2)] content-stretch flex items-center justify-center relative rounded-[35px] shrink-0 size-[42px]`
const AVATAR_MUTED = String.raw`bg-[var(--colors\/slate\/200,#e2e8f0)] content-stretch flex items-center justify-center relative rounded-[35px] shrink-0 size-[42px]`
/* src/v2/icons/Waves is the same Phosphor glyph, exported into a 21-unit box at
   stroke 1.08063; the alert-card export is a 19.111-unit box at stroke 1.58861.
   The paths are proportionally identical, so the project glyph is reused and
   only the weight is corrected — in the 21-unit space it renders in, and via
   CSS, which outranks the per-path stroke-width attribute. */
const WAVES_WEIGHT = '[&_path]:[stroke-width:1.74563]'

const TITLE = String.raw`[word-break:break-word] font-sans font-[var(--font\/weight\/font-medium,500)] leading-[var(--text\/base\/lh,24px)] relative shrink-0 text-[color:var(--colors\/slate\/900,#0f172b)] text-[length:var(--text\/base\/size,16px)] whitespace-nowrap`
const TITLE_MUTED = String.raw`[word-break:break-word] font-sans font-[var(--font\/weight\/font-medium,500)] leading-[var(--text\/base\/lh,24px)] relative shrink-0 text-[color:var(--colors\/slate\/500,#62748e)] text-[length:var(--text\/base\/size,16px)] whitespace-nowrap`
const UNIT_WRAP = String.raw`[word-break:break-word] content-stretch flex font-sans font-[var(--font\/weight\/font-normal,400)] gap-[var(--spacing\/0\,5,2px)] items-center leading-[var(--text\/xs\/lh-none,12px)] relative shrink-0 text-[12px] whitespace-nowrap`
const UNIT_VALUE = String.raw`overflow-hidden relative shrink-0 text-[color:var(--colors\/slate\/900,#0f172b)] text-ellipsis`
const UNIT_VALUE_MUTED = String.raw`overflow-hidden relative shrink-0 text-[color:var(--colors\/slate\/700,#314158)] text-ellipsis`
const UNIT_LABEL = 'overflow-hidden relative shrink-0 text-[#62748e] text-ellipsis'

const COUNT_CHIP = String.raw`bg-[var(--colors\/slate\/200,#e2e8f0)] content-stretch flex flex-col items-center justify-center relative rounded-[6px] shrink-0 size-[18px]`
const COUNT_TEXT = String.raw`[word-break:break-word] font-sans font-[var(--font\/weight\/font-semibold,600)] leading-[var(--text\/base\/lh,24px)] relative shrink-0 text-[color:var(--colors\/slate\/900,#0f172b)] text-[length:var(--text\/base\/size,16px)] text-center w-full`
const GROUP_LABEL = String.raw`[word-break:break-word] flex flex-col font-sans font-[var(--font\/weight\/font-medium,500)] justify-center leading-[0] relative shrink-0 text-[color:var(--colors\/slate\/600,#45556c)] text-[length:var(--text\/base\/size,16px)] whitespace-nowrap`
const DOTS_BADGE = String.raw`content-stretch cursor-pointer flex gap-[var(--component\/badge\/gap,4px)] h-[20px] items-center justify-center overflow-clip px-[var(--component\/tabs\/trigger\/gap,6px)] py-[var(--component\/badge\/py,2px)] relative rounded-[var(--component\/badge\/radius,26px)] shrink-0 w-[14px]`

const STAT_BADGE = 'content-stretch flex gap-[4.8px] h-[24px] items-center justify-center overflow-clip px-[7.2px] py-[2.4px] relative rounded-[31.2px] shrink-0'
const STAT_VALUE_ALERT = String.raw`[word-break:break-word] font-mono-label font-medium leading-[23.04px] overflow-hidden relative shrink-0 text-[17.28px] text-[color:var(--colors\/red\/500,#fb2c36)] text-ellipsis whitespace-nowrap`
const STAT_VALUE_OK = String.raw`[word-break:break-word] font-sans font-[var(--font\/weight\/font-medium,500)] leading-[var(--text\/xs\/lh,19.2px)] overflow-hidden relative shrink-0 text-[14.4px] text-[color:var(--foreground,#0a0a0a)] text-ellipsis whitespace-nowrap`
/* The 17.28px wifi slot: Figma nests the leaf twice — an inset box, then a
   negative inset that re-adds the stroke bleed. Both are kept verbatim so the
   glyph lands where it was drawn. */
const WIFI_SLOT = 'overflow-clip relative shrink-0 size-[17.28px]'
const WIFI_INNER = 'absolute inset-[16.67%_8.33%_16.67%_8.34%]'
const WIFI_LEAF = 'absolute inset-[-7.12%_-5.7%]'

const SENSORS_TOTAL = String.raw`[word-break:break-word] font-sans font-[var(--font\/weight\/font-semibold,600)] leading-[var(--text\/base\/lh,24px)] relative shrink-0 text-[color:var(--colors\/slate\/900,#0f172b)] text-[length:var(--text\/base\/size,16px)] whitespace-nowrap`

/** Card shells. No `\/` in these, so plain strings are safe. */
const SHELL = 'bg-[#fafbfc] border border-solid border-white content-stretch flex flex-col h-[136px] items-start justify-center px-[18px] py-[12px] relative rounded-[var(--rounded-2xl,18px)] w-[308px]'
const SHELL_WATER_EVENT = `${SHELL} max-w-[440px]`
const SHELL_MOBILE = 'bg-[#fafbfc] border border-solid border-white content-stretch flex flex-col gap-[20px] h-[178px] items-start px-[18px] py-[12px] relative rounded-[var(--rounded-2xl,18px)] w-[308px]'
const INNER_COLUMN = 'content-stretch flex flex-[1_0_0] flex-col items-start justify-between min-h-px relative w-full'

/* Gradient stacks on the sensor stat badges. Each badge carries its own angle in
   the design (the gradient is baked per-instance), so they are not collapsed. */
const BADGE_SHEEN = (deg) =>
  `linear-gradient(${deg}deg, rgba(233, 238, 248, 0.8) 8.3855%, rgba(227, 235, 249, 0.8) 32.2%, rgba(228, 235, 250, 0.8) 40.822%, rgba(212, 226, 255, 0.8) 71.236%), linear-gradient(90deg, rgb(255, 255, 255) 0%, rgb(255, 255, 255) 100%)`

/* ── Mock data ─────────────────────────────────────────────────────────────
 * MOCK ONLY. Every string here is the literal copy on the Figma nodes, so an
 * unconfigured <AlertCard /> renders the design frame exactly. */
const MOCK_EVENT = {
  title: 'High flow event',
  value: '13,564',
  unit: 'L/H flow rate',
  status: 'Ongoing',
  detectedLabel: 'Detected',
  detectedAt: 'Apr 02, 2026 08:13:15',
  duration: '6h 36m',
  page: 1,
  pageCount: 2,
  sensorTotal: '7 Sensors',
  sensorGroups: [
    { key: 'flood', kind: 'flood', count: '3', label: 'Flood', offline: '1', alerting: '2', online: '3' },
    { key: 'humidity', kind: 'humidity', count: '4', label: 'Humidity', offline: '1', alerting: '2', online: '4' },
  ],
  empty: {
    title: 'Everything looks good!',
    body: 'No active water events',
    link: 'Show past events',
  },
}

/* ── Pieces shared across variants ─────────────────────────────────────────── */

/**
 * The "‹ 1 / 2 ›" pager. Figma models this as a single Button instance
 * (198379:80025) with two icon slots, not as two controls, so it stays one
 * button: the chevrons are aria-hidden decoration and the whole pill advances
 * to the next alert. They look individually tappable and deliberately are not —
 * splitting them would mean nesting buttons inside a button.
 */
function Pager({ page, pageCount, totalTone = 'text-[#90a1b9]', onClick }) {
  return (
    <Button
      type="button"
      size="xs"
      variant="secondary"
      onClick={onClick}
      aria-label={`Alert ${page} of ${pageCount}. Show next`}
      className={`${PAGER_BTN} ${CTRL_SHADOW}`}
    >
      <span className={ICON_SLOT}>
        <ChevronLeft className="block size-full" />
      </span>
      <p className={PAGER_LABEL}>
        <span className={`${PAGER_SPAN} text-[#62748e]`}>{page} /</span>
        <span className={PAGER_SPAN}>{' '}</span>
        {/* Reproduced as drawn. On Water event (198374:56324) the design tints
            the total `text-white`, which is all but invisible on the slate-100
            pill — Figma's own render of that frame shows "‹ 1 / ›". Ignored,
            Sensors and Sensors_Errors all use slate-400. Kept as designed
            rather than silently corrected; worth a question to the designer. */}
        <span className={`${PAGER_SPAN} ${totalTone}`}>{pageCount}</span>
      </p>
      <span className={ICON_SLOT}>
        <ChevronRight className="block size-full" />
      </span>
    </Button>
  )
}

/** The red/slate 42px avatar + title + rate block shared by the event cards. */
function EventSummary({ event, muted }) {
  return (
    <>
      <div className={muted ? AVATAR_MUTED : AVATAR_ALERT}>
        <div className="relative shrink-0 size-[19.111px]">
          <Waves
            size={19.111}
            className={`block size-full ${muted ? 'text-[#90a1b9]' : 'text-[#fb2c36]'} ${WAVES_WEIGHT}`}
          />
        </div>
      </div>
      <div className="flex flex-[1_0_0] flex-row items-center self-stretch">
        <div className="content-stretch flex flex-[1_0_0] flex-col h-full items-start justify-between min-w-px relative">
          <div className="content-stretch flex items-start relative shrink-0">
            <p className={muted ? TITLE_MUTED : TITLE} dir="auto">{event.title}</p>
          </div>
          <div className={UNIT_WRAP}>
            <p className={muted ? UNIT_VALUE_MUTED : UNIT_VALUE}>{event.value}</p>
            <p className={UNIT_LABEL}>{event.unit}</p>
          </div>
        </div>
      </div>
    </>
  )
}

/** "Detected · <timestamp> · <duration>". */
function DetectedRow({ event }) {
  return (
    <div className={META_ROW}>
      <p className={META_LABEL}>{event.detectedLabel}</p>
      <p className={META_TIME}>{event.detectedAt}</p>
      <p className={META_DURATION}>{event.duration}</p>
    </div>
  )
}

/**
 * A sensor group header: kind glyph, slate count chip, label, overflow menu.
 * The "…" is a Badge node in Figma with no cursor, but it is the only route to
 * that group's menu, so it renders as a real button rather than a div.
 */
function SensorGroupHeader({ group, onMore }) {
  return (
    <div className="content-stretch flex gap-[4px] items-center relative shrink-0 w-full">
      <div className="content-stretch flex gap-[5px] items-center relative shrink-0">
        <div className="relative shrink-0 size-[16px]">
          {group.kind === 'flood'
            ? <FloodLine size={16} className="block size-full text-[#62748e]" />
            : <BrandDrops size={16} className="block size-full text-[#62748e]" />}
        </div>
        <div className={COUNT_CHIP}>
          <p className={COUNT_TEXT} dir="auto">{group.count}</p>
        </div>
        <div className={GROUP_LABEL}>
          <p className="leading-[var(--text\/base\/lh,24px)]">{group.label}</p>
        </div>
      </div>
      <div className="content-stretch flex gap-[var(--spacing\/2,8px)] items-center relative rounded-bl-[8px] rounded-br-[8px] rounded-tl-[8px] shrink-0">
        <button
          type="button"
          onClick={onMore}
          aria-label={`More ${group.label} sensor options`}
          className={DOTS_BADGE}
        >
          <span className="content-stretch flex flex-col items-start relative rounded-[3px] shrink-0">
            <span className="h-[14px] relative shrink-0 w-[12px]">
              <DotsThree className="absolute block inset-0 max-w-none size-full" />
            </span>
          </span>
        </button>
      </div>
    </div>
  )
}

/** One sensor stat pill — the gradient sheen plus a blend layer, then icon + count. */
function StatBadge({ deg, blend, icon, value, valueClass }) {
  return (
    <Badge className={`${STAT_BADGE} border-0`}>
      <span aria-hidden className="absolute inset-0 pointer-events-none rounded-[31.2px]">
        <span className="absolute inset-0 rounded-[31.2px]" style={{ backgroundImage: BADGE_SHEEN(deg) }} />
        {blend === 'alert' ? (
          <>
            <span className="absolute bg-[rgba(255,58,58,0.01)] inset-0 mix-blend-multiply rounded-[31.2px]" />
            <span className="absolute bg-[#ff1717] inset-0 mix-blend-color rounded-[31.2px]" />
          </>
        ) : (
          <span className="absolute bg-[rgba(255,180,180,0.2)] inset-0 mix-blend-color rounded-[31.2px]" />
        )}
      </span>
      <span className="content-stretch flex flex-col items-start relative shrink-0">{icon}</span>
      <p className={valueClass}>{value}</p>
    </Badge>
  )
}

/* ── Component ─────────────────────────────────────────────────────────────── */

/**
 * @param {object}   props
 * @param {'mobile'|'water-event'|'ignored'|'sensors'|'sensors-errors'|'empty'} props.variant
 *        `mobile` is the 375px treatment (308x178, two full-width actions); the
 *        other five are the 308x136 desktop sizes of the same card.
 * @param {object}   props.event      copy + counts; defaults to MOCK_EVENT.
 * @param {Function} props.onAction   (actionId, event) => void. Ids:
 *        'paginate' | 'on-it' | 'ignore' | 'unignore' | 'action' |
 *        'sensor-more' | 'show-past-events'. Omit it and every control still
 *        renders and is focusable, it just no-ops.
 * @param {string}   props.className  appended to the card shell.
 */
export default function AlertCard({
  variant = 'mobile',
  event = MOCK_EVENT,
  onAction,
  className,
}) {
  const data = { ...MOCK_EVENT, ...event }
  const act = (id) => () => onAction?.(id, data)

  /* The card shell itself is inert by design — the Figma frame marks no tap
     target on it, only on the pills inside — so a caller that wants
     "tap the card to open the event" wraps it. */
  const shell = (cls, children) => (
    <div className={className ? `${cls} ${className}` : cls}>{children}</div>
  )

  if (variant === 'empty') {
    return shell(SHELL, (
      <div className="content-stretch flex flex-[1_0_0] gap-[var(--pro\/space\/4,16px)] items-center min-h-px relative w-full">
        <div className="h-[50.217px] relative shrink-0 w-[105px]">
          <div className="absolute inset-0 overflow-hidden pointer-events-none">
            <img alt="" src={EMPTY_ART} className="absolute h-[156.82%] left-0 max-w-none top-[-23.45%] w-full" />
          </div>
        </div>
        <div className="[word-break:break-word] content-stretch flex flex-[1_0_0] flex-col gap-[var(--pro\/space\/2,8px)] items-start justify-center min-w-px relative">
          <div className="content-stretch flex flex-col gap-[4px] items-start leading-[0] relative shrink-0 w-full">
            <div className="flex flex-col font-sans font-[var(--font\/weight\/font-semibold,600)] justify-center relative shrink-0 text-[color:var(--foreground,#0a0a0a)] text-[length:var(--text\/base\/size,16px)] w-full">
              <p className="leading-[var(--text\/base\/lh,24px)]">{data.empty.title}</p>
            </div>
            <div className="flex flex-col font-sans font-[var(--font\/weight\/font-normal,400)] justify-center relative shrink-0 text-[color:var(--muted-foreground,#737373)] text-[length:var(--text\/sm\/size,14px)] w-full">
              <p className="leading-[var(--text\/sm\/lh,20px)]" dir="auto">{data.empty.body}</p>
            </div>
          </div>
          <button
            type="button"
            onClick={act('show-past-events')}
            className="cursor-pointer font-sans font-[var(--font\/weight\/font-medium,500)] leading-[var(--text\/xs\/lh-tight,15px)] overflow-hidden relative shrink-0 text-[12px] text-[color:var(--wint-blue-accent,#0b81f8)] text-center text-ellipsis whitespace-nowrap"
          >
            {data.empty.link}
          </button>
        </div>
      </div>
    ))
  }

  if (variant === 'mobile') {
    return shell(SHELL_MOBILE, (
      <>
        <div className={INNER_COLUMN}>
          <div className="content-stretch flex items-center justify-between relative shrink-0 w-full">
            <div className="content-stretch flex gap-[4px] items-center relative shrink-0 w-[160px]">
              <Button
                type="button"
                size="xs"
                variant="secondary"
                onClick={act('paginate')}
                aria-label={`Alert ${data.page} of ${data.pageCount}. Show next`}
                className={String.raw`bg-[var(--colors\/slate\/200,#e2e8f0)] content-stretch cursor-pointer flex gap-[var(--spacing\/1,4px)] h-[24px] items-center justify-center px-[var(--component\/button\/size-xs\/px,10px)] py-[var(--p-0,0px)] relative rounded-[var(--component\/button\/size-xs\/radius,26px)] shrink-0 ${CTRL_SHADOW}`}
              >
                <p className={PAGER_LABEL}>
                  <span className={`${PAGER_SPAN} text-[#62748e]`}>{data.page} /</span>
                  <span className={PAGER_SPAN}>{' '}</span>
                  <span className={`${PAGER_SPAN} text-[#90a1b9]`}>{data.pageCount}</span>
                </p>
              </Button>
              {/* Figma draws "Ongoing" with the Button component, but it states
                  status and has no destination — a Badge, so it is not a dead
                  button. `destructive` is the matching Type and its
                  border-transparent keeps the pill borderless as drawn. */}
              <Badge
                variant="destructive"
                className={String.raw`bg-[var(--colors\/red\/500,#fb2c36)] content-stretch flex gap-[var(--spacing\/1,4px)] h-[24px] items-center justify-center px-[var(--component\/button\/size-xs\/px,10px)] py-[var(--p-0,0px)] relative rounded-[var(--component\/button\/size-xs\/radius,26px)] shrink-0 ${CTRL_SHADOW}`}
              >
                <span className="[word-break:break-word] font-sans font-medium leading-[var(--text\/button-xs\/size,12px)] relative shrink-0 text-[#fafbfc] text-[length:var(--text\/button-xs\/size,12px)] whitespace-nowrap">
                  {data.status}
                </span>
              </Badge>
            </div>
          </div>

          <div className="content-stretch flex gap-[11px] items-center relative shrink-0 w-full">
            <EventSummary event={data} />
          </div>

          <DetectedRow event={data} />
        </div>

        <div className="content-stretch flex gap-[12px] items-start relative shrink-0 w-full">
          <div className="content-stretch flex flex-[1_0_0] gap-[10px] items-center min-w-px relative">
            <Button
              type="button"
              size="xs"
              variant="outline"
              onClick={act('on-it')}
              className={String.raw`bg-[#f2f6ff] border border-[var(--wint-blue-accent,#0b81f8)] border-solid content-stretch cursor-pointer flex flex-[1_0_0] gap-[var(--spacing\/1,4px)] h-[27px] items-center justify-center min-w-px px-[var(--component\/button\/size-xs\/px,10px)] py-[var(--p-0,0px)] relative rounded-[var(--component\/button\/size-xs\/radius,26px)] ${CTRL_SHADOW}`}
            >
              <span className={BTN_BLUE_LABEL}>On it</span>
            </Button>
          </div>
          <div className="content-stretch flex flex-[1_0_0] gap-[10px] items-center min-w-px relative">
            <Button
              type="button"
              size="xs"
              variant="outline"
              onClick={act('ignore')}
              className={String.raw`bg-[#f2f6ff] border border-[var(--colors\/slate\/400,#90a1b9)] border-solid content-stretch cursor-pointer flex flex-[1_0_0] gap-[var(--spacing\/1,4px)] h-[27px] items-center justify-center min-w-px px-[var(--component\/button\/size-xs\/px,10px)] py-[var(--p-0,0px)] relative rounded-[var(--component\/button\/size-xs\/radius,26px)] ${CTRL_SHADOW}`}
            >
              <span className="[word-break:break-word] font-sans font-medium leading-[var(--text\/button-xs\/size,12px)] relative shrink-0 text-[color:var(--colors\/slate\/600,#45556c)] text-[length:var(--text\/button-xs\/size,12px)] whitespace-nowrap">
                Ignore
              </span>
            </Button>
          </div>
        </div>
      </>
    ))
  }

  if (variant === 'water-event') {
    return shell(SHELL_WATER_EVENT, (
      <div className={INNER_COLUMN}>
        <div className="content-stretch flex items-center justify-between relative shrink-0 w-full">
          <div className="content-stretch flex flex-[1_0_0] gap-[11px] items-center min-w-px relative">
            <EventSummary event={data} />
          </div>
        </div>

        <DetectedRow event={data} />

        <div className="content-stretch flex items-center justify-between relative shrink-0 w-full">
          <div className="content-stretch flex gap-[11px] items-center relative shrink-0">
            <Pager page={data.page} pageCount={data.pageCount} totalTone="text-white" onClick={act('paginate')} />
          </div>
          <Button
            type="button"
            size="xs"
            variant="outline"
            onClick={act('ignore')}
            className={`${BTN_BLUE} w-[56px] ${CTRL_SHADOW}`}
          >
            <span className={BTN_BLUE_LABEL}>Ignore</span>
          </Button>
        </div>
      </div>
    ))
  }

  if (variant === 'ignored') {
    return shell(SHELL, (
      <div className={INNER_COLUMN}>
        <div className="content-stretch flex gap-[11px] items-center relative shrink-0 w-full">
          <EventSummary event={data} muted />
        </div>

        <DetectedRow event={data} />

        <div className="content-stretch flex items-center justify-between relative shrink-0 w-full">
          <div className="content-stretch flex items-center relative shrink-0 w-[160px]">
            <Pager page={data.page} pageCount={data.pageCount} onClick={act('paginate')} />
          </div>
          {/* Drawn as a Badge in every respect (badge px / py / radius /
              border-width tokens) even though the node is named Button. It is
              the way back out of the ignored state, so it is interactive. */}
          <Badge
            variant="secondary"
            className={String.raw`bg-[var(--colors\/slate\/100,#f1f5f9)] border-[length:var(--component\/badge\/border-width,1px)] border-[var(--colors\/slate\/200,#e2e8f0)] border-solid content-stretch cursor-pointer flex gap-[var(--component\/badge\/gap,4px)] h-[24px] items-center justify-center px-[var(--component\/badge\/px,8px)] py-[var(--component\/badge\/py,2px)] relative rounded-[var(--component\/badge\/radius,26px)] shrink-0`}
            role="button"
            tabIndex={0}
            onClick={act('unignore')}
            onKeyDown={(e) => {
              if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); onAction?.('unignore', data) }
            }}
          >
            <span className="[word-break:break-word] font-sans font-[var(--font\/weight\/font-medium,500)] leading-[var(--text\/xs\/lh,16px)] relative shrink-0 text-[color:var(--colors\/slate\/400,#90a1b9)] text-[length:var(--text\/xs\/size,12px)] whitespace-nowrap">
              Ignored
            </span>
          </Badge>
        </div>
      </div>
    ))
  }

  const [flood, humidity] = data.sensorGroups

  /* 'sensors' and 'sensors-errors' are the same two group columns with the row
     order flipped and a different badge treatment: 'sensors' reports faults
     (red sheen, Geist numerals, wifi-disconnected + a kind-glyph count),
     'sensors-errors' reports the healthy roll-up (pink-tinted sheen, Figtree
     numerals, wifi-connected). */
  const alerting = variant === 'sensors'

  const sensorRow = (
    <div className={`content-stretch flex ${alerting ? 'gap-[32px] items-start' : 'items-start justify-between'} relative shrink-0 w-full`}>
      <div className="content-stretch flex items-center pr-[6px] pt-[6px] relative rounded-[14px] shrink-0">
        <div className="content-stretch flex flex-col gap-[7px] items-start relative shrink-0">
          <SensorGroupHeader group={flood} onMore={act('sensor-more')} />
          {alerting ? (
            <div className="content-stretch flex gap-[3px] items-start relative shrink-0">
              <div className="content-stretch flex items-center relative shrink-0">
                <div className="content-stretch flex items-end relative shrink-0">
                  <StatBadge
                    deg={162.45328003887474}
                    blend="alert"
                    valueClass={STAT_VALUE_ALERT}
                    value={flood.offline}
                    icon={
                      <span className={WIFI_SLOT}>
                        <span className={WIFI_INNER}>
                          <span className={WIFI_LEAF}>
                            <WifiDisconnected02 className="block max-w-none size-full text-[#fb2c36]" preserveAspectRatio="none" />
                          </span>
                        </span>
                      </span>
                    }
                  />
                </div>
              </div>
              <StatBadge
                deg={165.4952837287849}
                blend="alert"
                valueClass={STAT_VALUE_ALERT}
                value={flood.alerting}
                icon={
                  <span className="relative shrink-0 size-[19.2px]">
                    <FloodLine size={19.2} className="absolute block inset-0 max-w-none size-full text-[#fb2c36]" />
                  </span>
                }
              />
            </div>
          ) : (
            <div className="content-stretch flex items-start relative shrink-0">
              <div className="content-stretch flex items-center relative shrink-0">
                <div className="content-stretch flex items-end relative shrink-0">
                  <StatBadge
                    deg={163.24853141024147}
                    blend="ok"
                    valueClass={STAT_VALUE_OK}
                    value={flood.online}
                    icon={
                      <span className={WIFI_SLOT}>
                        <span className={WIFI_INNER}>
                          <span className={WIFI_LEAF}>
                            <WifiConnected02 className="block max-w-none size-full text-[#62748e]" />
                          </span>
                        </span>
                      </span>
                    }
                  />
                </div>
              </div>
            </div>
          )}
        </div>
      </div>

      <div className="content-stretch flex items-center pr-[6px] pt-[6px] relative rounded-[14px] shrink-0 w-[116px]">
        <div className="content-stretch flex flex-[1_0_0] flex-col gap-[7px] items-start min-w-px relative">
          <SensorGroupHeader group={humidity} onMore={act('sensor-more')} />
          {alerting ? (
            <div className="content-stretch flex gap-[3px] items-start relative shrink-0">
              <div className="content-stretch flex items-center relative shrink-0">
                <div className="content-stretch flex items-end relative shrink-0">
                  <StatBadge
                    deg={162.45328003887474}
                    blend="alert"
                    valueClass={STAT_VALUE_ALERT}
                    value={humidity.offline}
                    icon={
                      <span className={WIFI_SLOT}>
                        <span className={WIFI_INNER}>
                          <span className={WIFI_LEAF}>
                            <WifiDisconnected02 className="block max-w-none size-full text-[#fb2c36]" preserveAspectRatio="none" />
                          </span>
                        </span>
                      </span>
                    }
                  />
                </div>
              </div>
              <StatBadge
                deg={165.4952837287849}
                blend="alert"
                valueClass={STAT_VALUE_ALERT}
                value={humidity.alerting}
                icon={
                  <span className="relative shrink-0 size-[23.04px]">
                    <BrandDrops size={23.04} strokeWidth={0.8333} className="absolute block inset-0 max-w-none size-full text-[#fb2c36]" />
                  </span>
                }
              />
            </div>
          ) : (
            <div className="content-stretch flex items-start relative shrink-0">
              <div className="content-stretch flex items-center relative shrink-0">
                <StatBadge
                  deg={163.62044992486318}
                  blend="ok"
                  valueClass={STAT_VALUE_OK}
                  value={humidity.online}
                  icon={
                    <span className={WIFI_SLOT}>
                      <span className={WIFI_INNER}>
                        <span className={WIFI_LEAF}>
                          <WifiConnected02 className="block max-w-none size-full text-[#62748e]" />
                        </span>
                      </span>
                    </span>
                  }
                />
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  )

  const sensorControls = (
    <div className="content-stretch flex items-center justify-between relative shrink-0 w-full">
      <div className="content-stretch flex gap-[4px] items-center relative shrink-0 w-[160px]">
        <Pager page={data.page} pageCount={data.pageCount} onClick={act('paginate')} />
        <p className={SENSORS_TOTAL} dir="auto">{data.sensorTotal}</p>
      </div>
      <div className="content-stretch flex gap-[10px] items-center relative shrink-0">
        <Button
          type="button"
          size="xs"
          variant="outline"
          onClick={act('action')}
          className={`${BTN_BLUE} ${CTRL_SHADOW}`}
        >
          <span className={BTN_BLUE_LABEL}>Action</span>
        </Button>
      </div>
    </div>
  )

  return shell(SHELL, (
    <div className={INNER_COLUMN}>
      {alerting ? sensorRow : sensorControls}
      {alerting ? sensorControls : sensorRow}
    </div>
  ))
}
